PRIO={9:0,4:1,8:2,5:3}
def transform(g):
    bs=blocks_of(g)
    return [[min([bs[k][r][c] for k in range(4) if bs[k][r][c]], key=lambda v:PRIO[v]) for c in range(4)] for r in range(4)]
for gi,(i,o) in enumerate(demos):
    print(gi+1, transform(i)==o)
# dynamic variant: min rowcount asc, tie color desc
def transform2(g):
    bs=blocks_of(g)
    def key(v):
        k=COL.index(v); b=bs[k]
        return (min(sum(x!=0 for x in row) for row in b), -v)
    return [[min([bs[k][r][c] for k in range(4) if bs[k][r][c]], key=key) for c in range(4)] for r in range(4)]
for gi,(i,o) in enumerate(demos):
    print('dyn',gi+1, transform2(i)==o)
